SELECT s.city, CASE WHEN s.rating >= 3.8 THEN 'high' WHEN s.rating >= 1.9 THEN 'mid' ELSE 'low' END AS rating_bucket, MIN(p.cost) AS min_cost, MAX(p.launch_date) AS last_launch_date FROM products p LEFT JOIN suppliers s ON s.id = p.supplier_id GROUP BY s.city, CASE WHEN s.rating >= 3.8 THEN 'high' WHEN s.rating >= 1.9 THEN 'mid' ELSE 'low' END ORDER BY rating_bucket, city LIMIT 5;
